 */

class CustomersController
{
    private static bool $columnsEnsured = false;
    private static bool $historyTableEnsured = false;

    private function ensureCustomersColumns(PDO $db): void
    {
        if (self::$columnsEnsured) {
            return;
        }
        self::$columnsEnsured = true;

        $columns = [
            'uid'           => 'VARCHAR(50) UNIQUE DEFAULT NULL',
            'phone'         => 'VARCHAR(50) DEFAULT NULL',
            'email'         => 'VARCHAR(100) DEFAULT NULL',
            'address'       => 'VARCHAR(255) DEFAULT NULL',
            'is_walkin'     => 'TINYINT(1) NOT NULL DEFAULT 0',
            'edited_by'     => 'INT NULL',
            'deleted_at'    => 'DATETIME NULL',
            'deleted_by'    => 'INT NULL',
            'delete_reason' => 'TEXT NULL',
        ];

        foreach ($columns as $column => $definition) {
            $stmt = $db->prepare("SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'customers' AND COLUMN_NAME = :column");
            $stmt->execute(['column' => $column]);
            if (!$stmt->fetch()) {
                $db->exec("ALTER TABLE customers ADD COLUMN $column $definition");
            }
        }
    }

    private function ensureCustomerHistoryTable(PDO $db): void
    {
        if (self::$historyTableEnsured) {
            return;
        }
        self::$historyTableEnsured = true;

        $db->exec("CREATE TABLE IF NOT EXISTS customer_history (
            id INT AUTO_INCREMENT PRIMARY KEY,
            customer_id INT NOT NULL,
            edited_by INT NULL,
            action VARCHAR(50) NOT NULL,
            changes JSON NULL,
            reason TEXT NULL,
            created_at DATETIME NOT NULL,
            FOREIGN KEY (customer_id) REFERENCES customers(id),
            FOREIGN KEY (edited_by) REFERENCES users(id) ON DELETE SET NULL
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

        try {
            $db->exec("ALTER TABLE customer_history MODIFY edited_by INT NULL");
        } catch (\Throwable $e) {
            error_log("Suppressed exception in " . __METHOD__ . ": " . $e->getMessage());
        }
    }

    // Make sure the built-in "Walk-in" customer exists. It represents one-off
    // buyers (someone who walked in, not a registered customer). It is a normal
    // customer row (has history, orders, balance, etc.) but flagged is_walkin = 1
    // so the sale/order form knows to ask "who was this buyer?" per order. Only
    // created once; if the user deletes it they can restore it like any customer.
    // Mirror of SuppliersController::ensureWalkbySupplier.
    private function ensureWalkinCustomer(PDO $db): void
    {
        $exists = $db->query('SELECT id FROM customers WHERE is_walkin = 1 LIMIT 1')->fetch();
        if ($exists) return;

        $uid = 'CUS-' . date('Ymd') . '-WALKIN';
        $stmt = $db->prepare('INSERT INTO customers (uid, name, is_walkin, created_by, created_at) VALUES (:uid, :name, 1, :created_by, NOW())');
        $stmt->execute([
            'uid'        => $uid,
            'name'       => 'Walk-in (one-off customer)',
            'created_by' => $_SESSION['user_id'] ?? null,
        ]);
    }

    public function index(): void
    {
        $db = Database::getConnection();
        $this->ensureCustomersColumns($db);
        $this->ensureWalkinCustomer($db);
        if (function_exists('ensureDefaultCatalogSeeded')) {
            ensureDefaultCatalogSeeded($db);
        }

        $showDeleted = isset($_GET['show_deleted']) && $_GET['show_deleted'] === 'true';

        if ($showDeleted) {
            $customers = $db->query('SELECT * FROM customers ORDER BY id DESC')->fetchAll();
        } else {
            $customers = $db->query('SELECT * FROM customers WHERE deleted_at IS NULL ORDER BY id DESC')->fetchAll();
        }

        Response::json(['customers' => $customers]);
    }

    public function store(array $data): void
    {
        try {
            $name = trim($data['name'] ?? '');
            if ($name === '') {
                Response::json(['error' => 'Customer name required'], 400);
                return;
            }

            $db = Database::getConnection();
            $this->ensureCustomersColumns($db);
            $this->ensureCustomerHistoryTable($db);

            // Generate UID: CUS-YYYYMMDD-XXXXXX (matching product/category format)
            $uid = 'CUS-' . date('Ymd') . '-' . strtoupper(substr(uniqid(), -6));

            $stmt = $db->prepare('INSERT INTO customers (uid, name, phone, email, address, created_by, created_at) VALUES (:uid, :name, :phone, :email, :address, :created_by, NOW())');
            $stmt->execute([
                'uid'        => $uid,
                'name'       => $name,
                'phone'      => $data['phone'] ?? null,
                'email'      => $data['email'] ?? null,
                'address'    => $data['address'] ?? null,
                'created_by' => $_SESSION['user_id'] ?? null,
            ]);

            $customerId = (int)$db->lastInsertId();

            // Log creation
            $histStmt = $db->prepare('INSERT INTO customer_history (customer_id, edited_by, action, changes, created_at) VALUES (:cid, :by, :action, :changes, NOW())');
            $histStmt->execute([
                'cid'     => $customerId,
                'by'      => $_SESSION['user_id'] ?? 1,
                'action'  => 'created',
                'changes' => json_encode(['uid' => $uid, 'name' => $name, 'phone' => $data['phone'] ?? null, 'email' => $data['email'] ?? null, 'address' => $data['address'] ?? null]),
            ]);

            SystemLog::write('customers', 'created', $customerId, $name, json_encode([
                'uid' => $uid,
                'phone' => $data['phone'] ?? null,
                'email' => $data['email'] ?? null,
                'status' => 'active'
            ]));

            Response::json(['id' => $customerId, 'uid' => $uid], 201);
        } catch (\Throwable $e) {
            error_log('[CUSTOMERS STORE ERROR] ' . $e->getMessage());
            Response::json(['error' => 'Failed to create customer. Please check server error logs.'], 500);
        }
    }

    public function update(string $id, array $data): void
    {
        try {
            $db = Database::getConnection();
            $this->ensureCustomersColumns($db);
            $this->ensureCustomerHistoryTable($db);

