​‌‌‌​‌​‌​‌‌​‌‌‌​​‌‌​​​​‌​‌‌‌​‌​‌​‌‌‌​‌​​​‌‌​‌​​​​‌‌​‌‌‌‌​‌‌‌​​‌​​‌‌​‌​​‌​‌‌‌‌​‌​​‌‌​​‌​‌​‌‌​​‌​​​​‌​​​​​​‌‌‌​‌‌​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌​​​‌‌​​​​‌​‌‌‌​‌​​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌‌​​​‌​​​​​​‌‌​​​​‌​‌‌​‌‌‌​​‌‌​​‌​​​​‌​​​​​​‌​​‌‌​‌​‌​‌​‌​‌​‌​‌​​‌‌​‌​‌​‌​​​​‌​​​​​​‌​​​​‌​​‌​​​‌​‌​​‌​​​​​​‌​‌​​‌​​‌​​​‌​‌​‌​​​‌‌​​‌​‌​‌​‌​‌​‌​​‌‌​‌​​​‌​‌​‌​​​‌​​​​‌​​​​​​‌​​‌​​‌​‌​​‌‌​‌​‌​​‌‌​‌​‌​​​‌​‌​‌​​​‌​​​‌​​‌​​‌​‌​​​​​‌​‌​‌​‌​​​‌​​​‌​‌​‌​​‌‌​​​‌​‌‌​​‌​​‌​‌‌‌​﻿‍ */
            }

            // Track changes
            $changes = [];
            foreach (['name', 'phone', 'email', 'address'] as $field) {
                if (array_key_exists($field, $data) && (string)($data[$field] ?? '') !== (string)($customer[$field] ?? '')) {
                    $changes[$field] = ['from' => $customer[$field], 'to' => $data[$field]];
                }
            }

            $stmt = $db->prepare('UPDATE customers SET name = :name, phone = :phone, email = :email, address = :address, edited_by = :edited_by, updated_at = NOW() WHERE id = :id');
            $stmt->execute([
                'name'      => $data['name'] ?? $customer['name'],
                'phone'     => $data['phone'] ?? $customer['phone'],
                'email'     => $data['email'] ?? $customer['email'],
                'address'   => $data['address'] ?? $customer['address'],
                'edited_by' => $_SESSION['user_id'] ?? null,
                'id'        => $id,
            ]);

            if (!empty($changes)) {
                $histStmt = $db->prepare('INSERT INTO customer_history (customer_id, edited_by, action, changes, created_at) VALUES (:cid, :by, :action, :changes, NOW())');
                $histStmt->execute([
                    'cid'     => $id,
                    'by'      => $_SESSION['user_id'] ?? 1,
                    'action'  => 'updated',
                    'changes' => json_encode($changes),
                ]);

                SystemLog::write('customers', 'updated', (int)$id, $customer['name'], json_encode(array_merge(
                    ['uid' => $customer['uid'] ?? null],
                    $changes
                )));
            }

            Response::json(['ok' => true]);
        } catch (\Throwable $e) {
            error_log('[CUSTOMERS UPDATE ERROR] ' . $e->getMessage());
            Response::json(['error' => 'Failed to update customer. Please check server error logs.'], 500);
        }
    }

    public function destroy(string $id): void
    {
        try {
            $db = Database::getConnection();
            $this->ensureCustomersColumns($db);
            $this->ensureCustomerHistoryTable($db);

            $stmt = $db->prepare('SELECT id, name, uid, is_walkin, deleted_at FROM customers WHERE id = :id');
            $stmt->execute(['id' => $id]);
            $customer = $stmt->fetch();
            if (!$customer) {
                Response::json(['error' => 'Customer not found'], 404);
                return;
            }

            if ($customer['deleted_at'] !== null) {
                Response::json(['error' => 'Customer is already deleted'], 400);
                return;
            }

            if (!empty($customer['is_walkin']) || str_starts_with(strtolower(trim((string)$customer['name'])), 'walk-in')) {
                Response::json(['error' => 'Walk-in Customer is a permanent system record and cannot be deleted'], 400);
                return;
            }

            $input = json_decode(file_get_contents('php://input'), true);
            $deleteReason = trim($input['delete_reason'] ?? '');
            if ($deleteReason === '') {
                Response::json(['error' => 'Deletion reason is required'], 400);
                return;
            }

            $stmt = $db->prepare('UPDATE customers SET deleted_at = NOW(), deleted_by = :deleted_by, delete_reason = :delete_reason WHERE id = :id');
            $stmt->execute([
                'deleted_by'    => $_SESSION['user_id'] ?? null,
                'delete_reason' => $deleteReason,
                'id'            => $id,
            ]);

            $histStmt = $db->prepare('INSERT INTO customer_history (customer_id, edited_by, action, reason, created_at) VALUES (:cid, :by, :action, :reason, NOW())');
            $histStmt->execute([
                'cid'    => $id,
                'by'     => $_SESSION['user_id'] ?? 1,
                'action' => 'deleted',
                'reason' => $deleteReason,
            ]);

            SystemLog::write('customers', 'deleted', (int)$id, $customer['name'], json_encode([
                'uid' => $customer['uid'] ?? null,
                'reason' => $deleteReason,
                'status' => 'deleted'
            ]));

            Response::json(['ok' => true]);
        } catch (\Throwable $e) {
            error_log('[CUSTOMERS DESTROY ERROR] ' . $e->getMessage());
            Response::json(['error' => 'Failed to delete customer. Please check server error logs.'], 500);
        }
    }

    public function restore(string $id): void
    {
        try {
            $db = Database::getConnection();
            $this->ensureCustomersColumns($db);
            $this->ensureCustomerHistoryTable($db);

            $stmt = $db->prepare('SELECT id, name, deleted_at FROM customers WHERE id = :id');
            $stmt->execute(['id' => $id]);
            $customer = $stmt->fetch();
            if (!$customer) {
                Response::json(['error' => 'Customer not found'], 404);
                return;
            }

            if ($customer['deleted_at'] === null) {
                Response::json(['error' => 'Customer is not deleted'], 400);
                return;
            }

            $input = json_decode(file_get_contents('php://input'), true);
            $restoreReason = trim($input['restore_reason'] ?? '');
            if ($restoreReason === '') {
                Response::json(['error' => 'Restore reason is required'], 400);
                return;
            }

            $stmt = $db->prepare('UPDATE customers SET deleted_at = NULL, deleted_by = NULL, delete_reason = NULL WHERE id = :id');
            $stmt->execute(['id' => $id]);

            $histStmt = $db->prepare('INSERT INTO customer_history (customer_id, edited_by, action, reason, created_at) VALUES (:cid, :by, :action, :reason, NOW())');
            $histStmt->execute([
                'cid'    => $id,
                'by'     => $_SESSION['user_id'] ?? 1,
                'action' => 'restored',
                'reason' => $restoreReason,
            ]);

            SystemLog::write('customers', 'restored', (int)$id, $customer['name'], json_encode([
                'uid' => $customer['uid'] ?? null,
                'reason' => $restoreReason,
                'status' => 'active'
            ]));

            Response::json(['ok' => true]);
        } catch (\Throwable $e) {
            error_log('[CUSTOMERS RESTORE ERROR] ' . $e->getMessage());
            Response::json(['error' => 'Failed to restore customer. Please check server error logs.'], 500);
        }
    }

    public function history(string $id): void
    {
        $db = Database::getConnection();
        $this->ensureCustomersColumns($db);
        $this->ensureCustomerHistoryTable($db);

        $stmt = $db->prepare('SELECT c.*, u.username as creator_name, u2.username as editor_name FROM customers c LEFT JOIN users u ON c.created_by = u.id LEFT JOIN users u2 ON c.edited_by = u2.id WHERE c.id = :id');
        $stmt->execute(['id' => $id]);
        $customer = $stmt->fetch();
        if (!$customer) {
            Response::json(['error' => 'Customer not found'], 404);
            return;
        }

        $stmt = $db->prepare('SELECT ch.*, u.username FROM customer_history ch LEFT JOIN users u ON ch.edited_by = u.id WHERE ch.customer_id = :id ORDER BY ch.created_at DESC');
        $stmt->execute(['id' => $id]);
        $history = $stmt->fetchAll();

        Response::json(['customer' => $customer, 'history' => $history]);
    }
}

